#nullable enable

using System;
using System.Collections.Generic;
using NeoCompose.Runtime.Json;
using UnityEngine;

namespace NeoCompose.Runtime
{
    /// <summary>
    /// Unity asset database generated by the Neo Compose editor sync.
    /// Maps Neo Compose file ids to imported Unity asset paths so runtime
    /// code can resolve file-backed attributes after a scene reload.
    /// </summary>
    public sealed class NeoAssetDatabase : ScriptableObject
    {
        [SerializeField]
        private List<NeoAssetDatabaseEntry> files = new();

        /// <summary>
        /// Loads the default synchronized asset database from Resources.
        /// Generated project loaders use this when the caller does not pass
        /// an explicit database.
        /// </summary>
        public static NeoAssetDatabase? LoadDefault()
        {
            return Resources.Load<NeoAssetDatabase>(NeoComposeDefaults.AssetDatabaseResourcePath);
        }

        /// <summary>
        /// Read-only entries keyed by Neo Compose file id.
        /// </summary>
        public IReadOnlyList<NeoAssetDatabaseEntry> Files => files;

        /// <summary>
        /// Returns the imported asset path for <paramref name="fileId"/>,
        /// or <c>null</c> when the file has not been synchronized yet.
        /// </summary>
        public string? TryGetAssetPath(string fileId)
        {
            var entry = TryGetEntry(fileId);
            return entry?.AssetPath;
        }

        /// <summary>
        /// Resolves a synchronized sprite by file id and canonical slice index.
        /// Falls back to Resources path loading when the serialized reference
        /// has not been populated yet.
        /// </summary>
        public Sprite? TryGetSprite(string fileId, int sliceIndex)
        {
            var entry = TryGetEntry(fileId);
            if (entry == null || sliceIndex < 0) return null;
            if (entry.Sprites.Length > sliceIndex && entry.Sprites[sliceIndex] != null)
            {
                return entry.Sprites[sliceIndex];
            }

            return null;
        }

        /// <summary>
        /// Resolves a synchronized audio clip by file id.
        /// </summary>
        public AudioClip? TryGetAudioClip(string fileId)
        {
            return TryGetEntry(fileId)?.AudioClip;
        }

        /// <summary>
        /// Reverse-resolves a Unity Sprite into the persisted file reference
        /// expected by Sprite attributes.
        /// </summary>
        public SpriteValue? TryGetValueForSprite(Sprite sprite)
        {
            var entry = TryGetEntryForSprite(sprite, out var sliceIndex);
            return entry == null
                ? null
                : new SpriteValue { fileId = entry.FileId, sliceIndex = sliceIndex };
        }

        /// <summary>
        /// Reverse-resolves a Unity AudioClip into the persisted file reference
        /// expected by Audio attributes.
        /// </summary>
        public FileValue? TryGetValueForAudioClip(AudioClip audioClip)
        {
            var entry = TryGetEntryForAudioClip(audioClip);
            return entry == null ? null : new FileValue { fileId = entry.FileId };
        }

        /// <summary>
        /// Reverse-resolves a Unity Sprite to its synchronized file metadata.
        /// </summary>
        public NeoAssetDatabaseEntry? TryGetEntryForSprite(Sprite sprite, out int sliceIndex)
        {
            sliceIndex = -1;
            if (sprite == null) return null;
            foreach (var entry in files)
            {
                for (var index = 0; index < entry.Sprites.Length; index++)
                {
                    if (entry.Sprites[index] == sprite)
                    {
                        sliceIndex = index;
                        return entry;
                    }
                }
            }

            return null;
        }

        /// <summary>
        /// Reverse-resolves a Unity AudioClip to its synchronized file metadata.
        /// </summary>
        public NeoAssetDatabaseEntry? TryGetEntryForAudioClip(AudioClip audioClip)
        {
            if (audioClip == null) return null;
            foreach (var entry in files)
            {
                if (entry.AudioClip == audioClip) return entry;
            }

            return null;
        }

        /// <summary>
        /// Returns the synchronized entry for <paramref name="fileId"/>,
        /// or <c>null</c> when the file has not been synchronized yet.
        /// </summary>
        public NeoAssetDatabaseEntry? TryGetEntry(string fileId)
        {
            if (string.IsNullOrWhiteSpace(fileId)) return null;
            foreach (var entry in files)
            {
                if (entry.FileId == fileId) return entry;
            }

            return null;
        }

        /// <summary>
        /// Upserts a file mapping after the editor has downloaded and
        /// imported the matching Unity asset.
        /// </summary>
        public void SetFile(
            string fileId,
            string fileName,
            string assetPath,
            string updatedAt,
            string lastDownloadedAt,
            string? templateId,
            string? templateUpdatedAt,
            string? lastAppliedTemplateEditsAt,
            string importSettingsVersion,
            Sprite[]? sprites = null,
            AudioClip? audioClip = null)
        {
            if (string.IsNullOrWhiteSpace(fileId))
            {
                throw new ArgumentException("File id cannot be empty.", nameof(fileId));
            }

            if (string.IsNullOrWhiteSpace(assetPath))
            {
                throw new ArgumentException("Asset path cannot be empty.", nameof(assetPath));
            }

            var entry = TryGetEntry(fileId);
            if (entry == null)
            {
                entry = new NeoAssetDatabaseEntry();
                files.Add(entry);
            }

            entry.FileId = fileId;
            entry.FileName = fileName;
            entry.AssetPath = assetPath;
            entry.FileUpdatedAt = updatedAt;
            entry.LastDownloadedAt = lastDownloadedAt;
            entry.TemplateId = templateId;
            entry.TemplateUpdatedAt = templateUpdatedAt;
            entry.LastAppliedTemplateEditsAt = lastAppliedTemplateEditsAt;
            entry.ImportSettingsVersion = importSettingsVersion;
            entry.Sprites = sprites ?? Array.Empty<Sprite>();
            entry.AudioClip = audioClip;
        }

        /// <summary>
        /// Returns stale file mappings whose ids are no longer present in the
        /// latest Neo Compose export.
        /// </summary>
        public NeoAssetDatabaseEntry[] FindMissingFiles(ISet<string> fileIds)
        {
            var missing = new List<NeoAssetDatabaseEntry>();
            foreach (var entry in files)
            {
                if (!fileIds.Contains(entry.FileId)) missing.Add(entry);
            }

            return missing.ToArray();
        }

        /// <summary>
        /// Removes a synchronized file mapping.
        /// </summary>
        public void RemoveFile(string fileId)
        {
            files.RemoveAll(entry => entry.FileId == fileId);
        }
    }

    /// <summary>
    /// Serialized mapping for a single synchronized file-backed Unity asset.
    /// </summary>
    [Serializable]
    public sealed class NeoAssetDatabaseEntry
    {
        [SerializeField]
        private string fileId = "";
        [SerializeField]
        private string fileName = "";
        [SerializeField]
        private string assetPath = "";
        [SerializeField]
        private string fileUpdatedAt = "";
        [SerializeField]
        private string lastDownloadedAt = "";
        [SerializeField]
        private string? templateId;
        [SerializeField]
        private string? templateUpdatedAt;
        [SerializeField]
        private string? lastAppliedTemplateEditsAt;
        [SerializeField]
        private string importSettingsVersion = "";
        [SerializeField]
        private Sprite[] sprites = Array.Empty<Sprite>();
        [SerializeField]
        private AudioClip? audioClip;

        /// <summary>Neo Compose file id.</summary>
        public string FileId
        {
            get => fileId;
            set => fileId = value;
        }

        /// <summary>Original Neo Compose file name.</summary>
        public string FileName
        {
            get => fileName;
            set => fileName = value;
        }

        /// <summary>Project-relative Unity asset path.</summary>
        public string AssetPath
        {
            get => assetPath;
            set => assetPath = value;
        }

        /// <summary>File metadata timestamp from project.json.</summary>
        public string FileUpdatedAt
        {
            get => fileUpdatedAt;
            set => fileUpdatedAt = value;
        }

        /// <summary>Timestamp when the file bytes were last downloaded.</summary>
        public string LastDownloadedAt
        {
            get => lastDownloadedAt;
            set => lastDownloadedAt = value;
        }

        /// <summary>Template id used for the last applied import settings.</summary>
        public string? TemplateId
        {
            get => templateId;
            set => templateId = value;
        }

        /// <summary>Template updatedAt timestamp used for the last import.</summary>
        public string? TemplateUpdatedAt
        {
            get => templateUpdatedAt;
            set => templateUpdatedAt = value;
        }

        /// <summary>Timestamp when template-backed edits were last applied.</summary>
        public string? LastAppliedTemplateEditsAt
        {
            get => lastAppliedTemplateEditsAt;
            set => lastAppliedTemplateEditsAt = value;
        }

        /// <summary>Neo Compose importer implementation version used for the last import.</summary>
        public string ImportSettingsVersion
        {
            get => importSettingsVersion;
            set => importSettingsVersion = value;
        }

        /// <summary>Imported sprites in canonical slice order.</summary>
        public Sprite[] Sprites
        {
            get => sprites ?? Array.Empty<Sprite>();
            set => sprites = value ?? Array.Empty<Sprite>();
        }

        /// <summary>Imported audio clip reference.</summary>
        public AudioClip? AudioClip
        {
            get => audioClip;
            set => audioClip = value;
        }
    }
}
